(ns metabase.metabot.tools.autogen-dashboard-test
  (:require
   [clojure.string :as str]
   [clojure.test :refer :all]
   [metabase.api-scope.core :as api-scope]
   [metabase.metabot.db :as metabot.db]
   [metabase.metabot.scope :as scope]
   [metabase.metabot.tools :as metabot.tools]
   [metabase.metabot.tools.autogen-dashboard :as autogen-dashboard]
   [metabase.metabot.tools.recoverable.common :as recoverable.common]
   [metabase.metabot.tools.run-query :as run-query]
   [metabase.test :as mt]))

(defn- invoke
  "Call `create_autogenerated_dashboard` with `source` the way the agent loop does, in a conversation that holds
  `queries`, in a profile that also has `search`. Return the result, or `{:output <the text the model reads>
  :error {:class :code}}` when the call fails."
  ([source] (invoke source {}))
  ([source queries]
   (let [entries (binding [scope/*current-user-scope* api-scope/unrestricted]
                   (metabot.tools/->entries [#'metabot.tools/create-autogenerated-dashboard-tool
                                             #'metabot.tools/search-tool]
                                            (atom {:state {:queries queries}})
                                            nil
                                            :internal))]
     ((:fn (get entries "create_autogenerated_dashboard")) {:source source}))))

(defn- dashboard
  "The result of a call that created the dashboard titled `title` at `url`."
  [title url]
  {:output     (str "The dashboard has been created and the user has been navigated to view it. Briefly "
                    "acknowledge this (1 sentence) and stop. Do not describe the dashboard contents.")
   :data-parts [{:type      :data
                 :data-type "generated_entity"
                 :data      {:type "dashboard" :url url :title title}}]})

(defn- failure
  "A call that failed with the declared error `code`, and the `lines` that the model reads."
  [code & lines]
  {:output (str/join "\n" lines)
   :error  {:class :recoverable :code code}})

(deftest dashboard-for-each-source-test
  (mt/with-temp [:model/Table {table-id :id :as table} {:name (mt/random-name) :db_id (mt/id)}
                 :model/Card  {model-id :id}            {:type :model :name "Test model"}
                 :model/Card  {metric-id :id}           {:type :metric :name "Test metric"}
                 :model/Card  {report-id :id}           {:type :question :name "Test report"}]
    (mt/with-current-user (mt/user->id :rasta)
      (testing "the model is told to acknowledge the dashboard in a sentence, and the frontend gets a link to it"
        (is (= (dashboard (or (:display_name table) (:name table)) (str "/auto/dashboard/table/" table-id))
               (invoke {:table_id table-id}))))
      (testing "each kind of source has its own X-ray path"
        (is (= (dashboard "Test model" (str "/auto/dashboard/model/" model-id))
               (invoke {:model_id model-id})))
        (is (= (dashboard "Test metric" (str "/auto/dashboard/metric/" metric-id))
               (invoke {:metric_id metric-id})))
        (is (= (dashboard "Test report" (str "/auto/dashboard/question/" report-id))
               (invoke {:report_id report-id}))))
      (testing "a query from the conversation is analyzed as it is"
        (is (= (dashboard "Dashboard" "/auto/dashboard/adhoc/q123")
               (invoke {:query_id "q123"} {"q123" {:lib/type :mbql/query :database (mt/id) :stages []}})))))))

(deftest unknown-query-id-test
  (testing "a query ID that the conversation doesn't hold fails, and the model reads the IDs that it does hold"
    (is (= (failure ::run-query/unknown-query-id "No query with ID q-9. Known query IDs: [q-1].")
           (invoke {:query_id "q-9"} {"q-1" {:lib/type :mbql/query :database (mt/id) :stages []}})))))

(deftest one-source-test
  (testing "a call that sets no source, or two, is rejected before any source is read"
    (doseq [source [{} {:table_id 1 :model_id 2}]]
      (is (= (failure ::autogen-dashboard/invalid-source
                      "Set exactly one of `table_id`, `model_id`, `metric_id`, `query_id` or `report_id` in `source`.")
             (invoke source)))))
  (testing "a null for an unused source is not a second source"
    (mt/with-temp [:model/Card {model-id :id} {:type :model}]
      (mt/with-current-user (mt/user->id :rasta)
        (is (=? {:data-parts [{:data {:url (str "/auto/dashboard/model/" model-id)}}]}
                (invoke {:table_id nil :model_id model-id})))))))

(deftest missing-source-test
  (mt/with-current-user (mt/user->id :rasta)
    (doseq [[source-key noun] {:table_id  "Table"
                               :model_id  "Model"
                               :metric_id "Metric"
                               :report_id "Question"}]
      (testing noun
        (is (= (failure ::recoverable.common/not-found
                        (str noun " 999999 was not found. It may not exist, or you may not have access to it.")
                        "Call `search` to find the entity you want and use an id from the results.")
               (invoke {source-key 999999})))))))

(deftest unreadable-source-test
  (mt/with-non-admin-groups-no-root-collection-perms
    (mt/with-temp [:model/Collection {coll-id :id}     {}
                   :model/Card       {model-id :id}    {:name "Secret model" :type :model :collection_id coll-id}
                   :model/Card       {metric-id :id}   {:name "Secret metric" :type :metric :collection_id coll-id}
                   :model/Card       {question-id :id} {:name "Secret question" :type :question :collection_id coll-id}
                   :model/Table      {table-id :id}    {:name "Secret table" :db_id (mt/id)}]
      (mt/with-no-data-perms-for-all-users!
        (doseq [[source-key id noun] [[:model_id model-id "Model"]
                                      [:metric_id metric-id "Metric"]
                                      [:report_id question-id "Question"]
                                      [:table_id table-id "Table"]]]
          (testing noun
            (testing "fails for a user who cannot read it, the same way a missing one does"
              (is (= (failure ::recoverable.common/not-found
                              (str noun " " id " was not found. It may not exist, or you may not have access to it.")
                              "Call `search` to find the entity you want and use an id from the results.")
                     (mt/with-current-user (mt/user->id :rasta)
                       (invoke {source-key id})))))
            (testing "still gets an admin a dashboard"
              (is (=? {:data-parts [{:data {:title #"Secret .*"}}]}
                      (mt/with-current-user (mt/user->id :crowberto)
                        (invoke {source-key id})))))))))))

(deftest unavailable-source-test
  (mt/with-temp [:model/Card  {model-id :id} {:type :model :archived true}
                 :model/Table {table-id :id} {:name (mt/random-name) :db_id (mt/id) :active false}]
    (mt/with-current-user (mt/user->id :rasta)
      (testing "an archived source the user can read is in the trash"
        (is (= (failure ::autogen-dashboard/unavailable-source
                        (str "Model " model-id " is in the trash.")
                        "Call `search` to find another source and use an id from the results.")
               (invoke {:model_id model-id}))))
      (testing "an inactive table is gone from its database"
        (is (= (failure ::autogen-dashboard/unavailable-source
                        (str "Table " table-id " is no longer in its database.")
                        "Call `search` to find another source and use an id from the results.")
               (invoke {:table_id table-id})))))))

(deftest unexpected-error-test
  (testing "an error that no one declared ends the turn"
    (mt/with-dynamic-fn-redefs [metabot.db/table (fn [_] (throw (ex-info "boom" {})))]
      (is (= {:class :unrecoverable :code :internal}
             (:error (invoke {:table_id 1})))))))
